import math

class Solution:
    def __init__(self):
        self.happy_string = ''

    def getHappyString(self, n: int, k: int) -> str:
        # determine starting character
        poss_per_group = 2 ** (n - 1)
        group_num = math.ceil(k / poss_per_group) - 1
        starting_char = ''

        # check to make sure there are at least k happy strings
        if k > poss_per_group * 3:
            return ''

        if group_num == 0:
            self.happy_string += 'a'
        elif group_num == 1:
            self.happy_string += 'b'
        else:
            self.happy_string += 'c'

        self.findNextChar(group_num, n - 1, group_num * poss_per_group, (group_num + 1) * poss_per_group, k)
        return self.happy_string

    def findNextChar(self, char_index: int, n: int, start: int, end: int, k: int) -> None:
        if n != 0:
            lower_index = -1
            upper_index = -1

            # 0 = 'a', 1 = 'b', 2 = 'c'
            if char_index == 0:
                lower_index = 1
                upper_index = 2
            elif char_index == 1:
                lower_index = 0
                upper_index = 2
            else:
                lower_index = 0
                upper_index = 1

            midpoint = int((start + end ) / 2)
            if (k <= midpoint):
                self.happy_string += self.indexToStr(lower_index)
                self.findNextChar(lower_index, n - 1, start, midpoint, k)
            else:
                self.happy_string += self.indexToStr(upper_index)
                self.findNextChar(upper_index, n - 1, midpoint, end, k)                

    def indexToStr(self, index: int) -> str:
        if index == 0:
            return 'a'
        elif index == 1:
            return 'b'
        else:
            return 'c'

def string_hash(s):
    a = sum(ord(c) for c in s)
    b = sum(ord(b) - ord(a) for a, b in zip(s, s[1:]))
    c = (a | b) & (~a << 2)
    return c ^ (32 * (s.count(" ") + 1))

class Solution:
    def pancakeSort(self, A: List[int]) -> List[int]:
        n = len(A)
        res = []

        for x in range(n, 1, -1):
            idx = A.index(x)
            res.extend([idx + 1, x])
            A = A[idx::-1] + A[idx+1:]
            A = A[x-1::-1]

        return res

def bingo(card, numbers):

    rc, cc, dc = [0]*5, [0]*5, [1]*2            # rows count, columns count, diag counts
    rc[2] = cc[2] = 1                           # preaffect 'FREE SPACE'
    s = set(numbers)

    for x,line in enumerate(card[1:]):
        for y,(c,n) in enumerate(zip(card[0], line)):
            tile = f'{c}{n}'
            if tile in s:
                rc[x] += 1
                cc[y] += 1
                if x == y:   dc[0] += 1         # main diag
                if x+y == 4: dc[1] += 1         # secundary diag
    return 5 in rc + cc + dc

