class Solution:
     def calculate(self, s):
         """
         :type s: str
         :rtype: int
         """

         if not s:
             return 0

         pre_op = '+'
         stack = [0]
         cur_num = 0
         digits = '0123456789'
         s += '#'

         for c in s:
             if c == ' ':
                 continue

             if c in digits:
                 cur_num = cur_num * 10 + int(c)
                 continue

             if pre_op == '-':
                 cur_num *= -1
             elif pre_op == '*':
                 cur_num *= stack.pop()
             elif pre_op == '/':
                 if cur_num == 0:
                     return None

                 pre_num = stack.pop()
                 flag = 1 if pre_num > 0 else -1
                 cur_num = abs(pre_num) // cur_num * flag

             stack.append(cur_num)
             pre_op = c
             cur_num = 0

         return sum(stack)

from math import sqrt
 class Solution:
     def largestDivisibleSubset(self, nums):
         """
         :type nums: List[int]
         :rtype: List[int]
         """
         nums.sort()
         l, prev = {}, {}  # length, previous number(largest divisor in nums)
         max_l, end_number = 0, None

         for i in nums:
             tmp_l, tmp_prev = 0, None
             for j in range(1, 1 + int(sqrt(i))):
                 if i % j == 0:
                     tmp = i // j
                     if tmp in prev and l[tmp] > tmp_l:
                         tmp_l, tmp_prev = l[tmp], tmp
                     if j in prev and l[j] > tmp_l:
                         tmp_l, tmp_prev = l[j], j                    

             tmp_l += 1
             prev[i], l[i] = tmp_prev, tmp_l

             if tmp_l > max_l:
                 max_l, end_number = tmp_l, i

         ans = []
         while end_number is not None:
             ans.append(end_number)
             end_number = prev[end_number]

         return ans

