def minor_or_major(chord):
    chord = tuple(chord.split()) if isinstance(chord, str) else ""
    return DCT_CHORDS.get(chord, "Not a chord")

def reverse_in_parentheses(s):
    stack = []
    for i in s:
        stack.append(i)

        if i == ')':
            opening = len(stack) - stack[::-1].index('(') - 1
            stack.append(''.join([i[::-1].translate(str.maketrans('()',')(')) for i in stack[opening:][::-1]]))  
            del stack[opening:-1]

    return ''.join(stack)

class Solution:
    def partitionDisjoint(self, A: List[int]) -> int:
        biggest = A[0]
        newbiggest = A[0]
        lenL = 1
        total = 1
        for itr in A[1:]:
            total += 1
            if itr < biggest:
                lenL = total
                biggest = newbiggest
            else:
                if itr > newbiggest:
                    newbiggest = itr
        return lenL

