class Solution:
    def countTriplets(self, A: List[int]) -> int:
        counters = [0] * (1 << 16)
        counters[0] = len(A)
        for num in A:
            mask = (~num) & ((1 << 16) - 1)
            sm = mask
            while sm != 0:
                counters[sm] += 1
                sm = (sm - 1) & mask

        return sum(counters[num1 & num2] for num1 in A for num2 in A)

class Solution:
     def __init__(self):
         self.k = 0
         self.result = None

     def kthSmallest(self, root, k):
         """
         :type root: TreeNode
         :type k: int
         :rtype: int
         """
         if root.left and self.k < k:
             self.kthSmallest(root.left, k)
         self.k += 1
         if self.k == k:
             self.result = root.val
         if root.right and self.k < k:
             self.kthSmallest(root.right, k)
         return self.result

