from collections import Counter

def runoff(voters):
    while voters[0]:
        poll = Counter(ballot[0] for ballot in voters)
        winner, maxscore = max(poll.items(), key = lambda x: x[1])
        minscore = min(poll.values())
        if maxscore * 2 > len(voters):
            return winner
        voters = [[c for c in voter if poll[c] > minscore] for voter in voters]

class Solution:
    def numDupDigitsAtMostN(self, N: int) -> int:
        # N -> total numbers less than or equal to N
        # We will calculate the integers with all different digits (which are less than/equal to N)
        # Then the answer would be: N - nums_with_different_digits

        # Calculate the number of digits in N
        NN, dd = N, 0
        nums = [] # store the digits
        while(NN):
            dd += 1
            nums.append(NN % 10)
            NN //= 10
        nums.reverse()


        # numbers with less digits than that of N
        numbers = 0
        for i in range(dd-1):
            numbers += 9 * (math.factorial(9) // math.factorial(9-i))


        # find the N-digit numbers (all-different)
        already_visited_digits = set()

        def fac2(n, k):
            return math.factorial(n) // math.factorial(n-k)

        for i,n in enumerate(nums):
            k = 0
            for j in range((1 if i==0 else 0), (n+1 if i==dd-1 else n)):
                if(j in already_visited_digits):
                    continue
                k += 1
            numbers += k * fac2(10-i-1, dd-i-1)
            if n in already_visited_digits:
                # All the numbers with this prefix will have at least one common digit
                break
            already_visited_digits.add(n)

        return N - numbers

def string_expansion(s):
    m,n = '',1
    for j in s:
        if j.isdigit():
            n = int(j)
        else:
            m += j*n
    return m

class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        if not position:
            return 0

        posToSpeed = {position[i]: speed[i] for i in range(len(position))}
        position.sort()

        leaderTime = (target - position[-1]) / posToSpeed[position[-1]]
        currGroups = 1
        for i in range(len(position) - 2, -1, -1):
            currTime = (target - position[i]) / posToSpeed[position[i]]
            if currTime > leaderTime:
                currGroups += 1
                leaderTime = currTime

        return currGroups
